import { createDataTable } from '@/components/ui/data-table';

const tabela = createDataTable({
  columns: colunas,
  data: linhas,
  enableRowSelection: true,
  enableColumnFilters: true,
  enableColumnPinning: true,
  globalFilterPlaceholder: 'Buscar...',
  caption: 'Pedidos do trimestre',                  // Vira <caption> fora da tela
  rowKey: (pedido) => pedido.id,    // Identidade estável da linha
});

document.body.appendChild(tabela);

import { createDataTable } from '@/components/ui/data-table';

const table = createDataTable({
  columns: columns,
  data: rows,
  enableRowSelection: true,
  enableColumnFilters: true,
  enableColumnPinning: true,
  globalFilterPlaceholder: 'Search...',
  caption: 'Orders this quarter',                  // Becomes an off-screen <caption>
  rowKey: (order) => order.id,    // Stable row identity
});

document.body.appendChild(table);

import { createDataTable } from '@/components/ui/data-table';

const tabla = createDataTable({
  columns: columnas,
  data: filas,
  enableRowSelection: true,
  enableColumnFilters: true,
  enableColumnPinning: true,
  globalFilterPlaceholder: 'Buscar...',
  caption: 'Pedidos del trimestre',                  // Se vuelve un <caption> fuera de pantalla
  rowKey: (pedido) => pedido.id,    // Identidad estable de la fila
});

document.body.appendChild(tabla);
